104:   const acc = new Map();
105:   latestAcc = acc;
106: 
107:   ctx.on("session/event", (session, event) => {
108:     if (event?.type !== "assistant/message") return;
109:     const u = readUsage(event);
110:     if (!u) return;
111:     const id = session?.header?.id ?? session?.id;
112:     if (id === undefined) return;
